. $PSScriptRoot/common.ps1
$checks=@(); $checks += [pscustomobject]@{Service='Backend';Status=$(try{(Invoke-RestMethod 'http://localhost:8000/api/health' -TimeoutSec 3).backend}catch{'Unavailable'})}; $checks += [pscustomobject]@{Service='Database';Status=$(if(Test-Command docker){try{docker compose --project-directory (Get-ProjectRoot) exec -T postgres pg_isready 2>$null|Out-Null;'Healthy'}catch{'Unavailable'}}else{'Docker not installed'})}; $checks += [pscustomobject]@{Service='Ollama';Status=$(try{Invoke-RestMethod 'http://localhost:11434/api/tags' -TimeoutSec 3|Out-Null;'Healthy'}catch{'Unavailable'})}; $checks|Format-Table -AutoSize
